def add(key, topic, kind, stem, answer, explanation, rubric=None, choices=None,
        difficulty='보통', correction='', references=(), material=None):
    q = dict(id='PQ-'+key, caseId='PC-'+key, topic=topic, kind=kind, difficulty=difficulty,
             skill='개념 적용', mistake='개념', stem=stem, explanation=explanation,
             steps=(rubric or [answer, explanation]), commonError=correction or '용어의 정의와 적용 조건을 함께 확인하세요.',
             lessonId='', sources=[], origin='사용자 제공 기출 복습',
             past=dict(status='기출 복원', occurrences=[], references=[dict(title=refs[r][0], url=refs[r][1]) for r in references]))
    if correction: q['past']['correction'] = correction
    if material: q['past']['material'] = material
    if kind == 'choice':
        q['choices'] = [dict(id=str(i+1), text=t, reason=r) for i,(t,r) in enumerate(choices)]
        q['correctId'] = str(answer)
    else:
        q['modelAnswer'] = answer[0] if isinstance(answer,list) else answer
        if kind == 'short': q['accepted'] = answer if isinstance(answer,list) else [answer]
        if kind == 'essay': q['rubric'] = rubric
    questions.append(q)
    return q['id']

def essay(k,t,s,a,r,e=None,**kw): return add(k,t,'essay',s,a,e or a,rubric=r,**kw)
def short(k,t,s,a,e,**kw): return add(k,t,'short',s,a,e,**kw)
def choice(k,t,s,cs,right,reasons,explanation,**kw):
    return add(k,t,'choice',s,right,explanation,choices=list(zip(cs,reasons)),**kw)
def occurrence(key, source, locator):
    q = next(q for q in questions if q['id']=='PQ-'+key)
    q['past']['occurrences'].append(dict(sourceId=source,locator=locator))
    return q['id']
def paper(pid,title,description,source,items,reconstructed=False):
    ids=[]
    for locator,key in items:
        ids.append(occurrence(key,source,str(locator)))
        if reconstructed:
            q=next(q for q in questions if q['id']=='PQ-'+key)
            if q['past']['status'] != '기출 복원' or all(o['sourceId']=='notes' and o['locator'].startswith('교재') for o in q['past']['occurrences']):
                q['past']['status']='정리자료 재구성';q['origin']='사용자 정리 기반 재구성'
    papers.append(dict(id=pid,title=title,description=description,questionIds=ids,category='정리자료 재구성' if reconstructed else '기출 복습'))
def review(source, locator, title, issue, resolution, replacement=None):
    reviews.append(dict(id='PR-'+str(len(reviews)+1),sourceId=source,locator=locator,title=title,issue=issue,resolution=resolution,replacement='PQ-'+replacement if replacement else None))

