playgrid=[['A','S','I','N','T'],['O','R','B','C','D'],['E','F','G','H','J'],['K','L','M','P','Q/Z'],['U','V','W','X','Y']]
pairs='BE CA RE FU LF OR AS SA SX SI NA TO RX'.split()
def playfair(pair):
    position={c:(i,j) for i,row in enumerate(playgrid) for j,value in enumerate(row) for c in value.split('/')}
    (r1,c1),(r2,c2)=[position[c] for c in pair]
    if r1==r2: out=[playgrid[r1][(c1+1)%5],playgrid[r2][(c2+1)%5]]
    elif c1==c2: out=[playgrid[(r1+1)%5][c1],playgrid[(r2+1)%5][c2]]
    else: out=[playgrid[r1][c2],playgrid[r2][c1]]
    return ''.join(out)
encrypted=[playfair(p) for p in pairs]
